import { resolveMarketStockId } from '@onekeyhq/kit/src/views/Market/MarketDetailV2/utils/resolveIsStockToken';
import { getPresetNetworks } from '@onekeyhq/shared/src/config/presetNetworks';
import type {
  IMarketBasicConfigNetwork,
  IMarketTokenListItem,
} from '@onekeyhq/shared/types/marketV2';

import type { IMarketTimeRangeValue } from '../../../types';
import type { IMarketToken } from '../MarketTokenData';

export function marketTokenKey(item: IMarketToken) {
  if (item.assetId) return `asset:${item.assetId}`;
  if (item.stockId) return `stock:${item.stockId}`;
  return item.perpsCoin
    ? `perps:${item.perpsCoin}`
    : `${item.networkId}:${(item.address || '').toLowerCase()}:${item.isNative ? 1 : 0}`;
}

// Helper function to check if token is native and get normalized address for matching
// Only uses fallback address length check when isNative field is not present (undefined)
// This ensures online data with isNative field won't use fallback logic
export function getNativeTokenInfo(
  isNativeField: boolean | undefined,
  address: string | undefined,
) {
  const isNative =
    isNativeField !== undefined ? isNativeField : (address?.length ?? 0) < 30;
  const normalizedAddress = isNative ? '' : (address ?? '').toLowerCase();
  return { isNative, normalizedAddress };
}

// Mapping of column keys to token fields, shared by multiple hooks
// These map API sort parameters to component token properties
export const SORT_MAP: Record<string, keyof IMarketToken> = {
  liquidity: 'liquidity',
  mc: 'marketCap',
  v24hUSD: 'turnover',
};

function getFiniteNumericSortValue(value: unknown) {
  if (
    value === null ||
    value === undefined ||
    (typeof value === 'string' && value.trim() === '')
  ) {
    return undefined;
  }
  const numericValue = Number(value);
  return Number.isFinite(numericValue) ? numericValue : undefined;
}

export function sortMarketTokenListData<T>({
  data,
  field,
  order,
}: {
  data: T[];
  field?: keyof T;
  order?: 'asc' | 'desc';
}) {
  if (!field || !order) {
    return data;
  }

  return [...data].toSorted((a, b) => {
    const aValue = getFiniteNumericSortValue(a[field]);
    const bValue = getFiniteNumericSortValue(b[field]);
    if (aValue === undefined) {
      return bValue === undefined ? 0 : 1;
    }
    if (bValue === undefined) {
      return -1;
    }
    return order === 'asc' ? aValue - bValue : bValue - aValue;
  });
}

export function normalizeStockMetadataValue(
  value?: string | number | null,
): string | undefined {
  if (value === null || value === undefined) {
    return undefined;
  }

  const stringValue = typeof value === 'string' ? value.trim() : String(value);
  if (!stringValue) {
    return undefined;
  }

  const numericValue = Number(stringValue);
  if (!Number.isFinite(numericValue)) {
    return undefined;
  }

  return stringValue;
}

export function getStockMarketCapValue(
  record: Pick<IMarketToken, 'stock'>,
): string | undefined {
  return normalizeStockMetadataValue(record.stock?.marketCap);
}

export function getStockVolume24hValue(
  record: Pick<IMarketToken, 'stock'>,
): string | undefined {
  return normalizeStockMetadataValue(record.stock?.assetAnalysis?.volume24h);
}

export function getStockPeRatioValue(
  record: Pick<IMarketToken, 'stock'>,
): string | undefined {
  return normalizeStockMetadataValue(record.stock?.tradingActivity?.peRatio);
}

export function shouldShowStockSubtitleForTokens(
  items: Array<Pick<IMarketToken, 'stock'>>,
) {
  if (items.length === 0) {
    return false;
  }

  const stockCount = items.filter((item) => !!item.stock).length;
  return stockCount >= items.length / 2;
}

export function shouldUseStockMetadataColumnsForTokens(
  items: Array<Pick<IMarketToken, 'stock'>>,
  options?: {
    forceStockMetadataColumns?: boolean;
    enableAutoDetection?: boolean;
  },
) {
  const { forceStockMetadataColumns = false, enableAutoDetection = true } =
    options ?? {};
  return (
    forceStockMetadataColumns ||
    (enableAutoDetection &&
      items.length > 0 &&
      items.every((item) => !!item.stock))
  );
}

const ONE_HOUR = 60 * 60 * 1000;
const ONE_DAY = 24 * ONE_HOUR;
const ONE_MONTH = 30 * ONE_DAY;
const ONE_YEAR = 12 * ONE_MONTH;

export type ITokenAgeUnit = 'hour' | 'day' | 'month' | 'year';

export interface ITokenAgeInfo {
  amount: number;
  unit: ITokenAgeUnit;
}

const TIME_RANGE_FIELD_SUFFIX_MAP: Record<
  IMarketTimeRangeValue,
  '5m' | '1h' | '4h' | '24h'
> = {
  '5m': '5m',
  '1h': '1h',
  '4h': '4h',
  '24h': '24h',
};

const TIME_RANGE_PRICE_BASE_FIELD_MAP: Record<
  IMarketTimeRangeValue,
  'price5mAgo' | 'price1hAgo' | 'price4hAgo' | 'price24hAgo'
> = {
  '5m': 'price5mAgo',
  '1h': 'price1hAgo',
  '4h': 'price4hAgo',
  '24h': 'price24hAgo',
};

export function getNetworkLogoUri(chainOrNetworkId: string): string {
  const networks = getPresetNetworks();
  const network = networks.find((n) => n.id === chainOrNetworkId);
  return network?.logoURI || '';
}

export function buildMarketNetworkLogoUriMap(
  networkList: readonly IMarketBasicConfigNetwork[],
) {
  return new Map<string, string>(
    networkList.map((network) => [network.networkId, network.logoUrl] as const),
  );
}

function safeNumber(value: string | undefined, fallback = 0): number {
  if (!value) return fallback;

  try {
    const numberValue = Number(value);
    if (!Number.isFinite(numberValue)) {
      return fallback;
    }
    return numberValue;
  } catch {
    return fallback;
  }
}

function safePositiveNumber(value: string | undefined): number | undefined {
  if (!value) {
    return undefined;
  }

  try {
    const numberValue = Number(value);
    if (!Number.isFinite(numberValue) || numberValue <= 0) {
      return undefined;
    }
    return numberValue;
  } catch {
    return undefined;
  }
}

function getMetricValueByTimeRange(
  item: IMarketTokenListItem,
  timeRange: IMarketTimeRangeValue | undefined,
  baseKey: 'priceChange' | 'trade' | 'buy' | 'sell' | 'uniqueWallet' | 'volume',
  suffix: 'Percent' | 'Count' | '',
) {
  const fieldSuffix = TIME_RANGE_FIELD_SUFFIX_MAP[timeRange ?? '24h'];
  const selectedKey =
    `${baseKey}${fieldSuffix}${suffix}` as keyof IMarketTokenListItem;
  const fallbackKey = `${baseKey}24h${suffix}` as keyof IMarketTokenListItem;

  return item[selectedKey] ?? item[fallbackKey];
}

function getPriceChangeBasePriceByTimeRange({
  item,
  timeRange,
}: {
  item: IMarketTokenListItem;
  timeRange: IMarketTimeRangeValue | undefined;
}) {
  const selectedTimeRange = timeRange ?? '24h';
  const selectedKey = TIME_RANGE_PRICE_BASE_FIELD_MAP[selectedTimeRange];
  return safePositiveNumber(item[selectedKey]);
}

export function calculateMarketTokenLivePriceChange({
  price,
  priceChangeBasePrice,
}: {
  price: number | undefined;
  priceChangeBasePrice: number | undefined;
}): number | undefined {
  if (price === undefined || priceChangeBasePrice === undefined) {
    return undefined;
  }

  if (
    !Number.isFinite(price) ||
    !Number.isFinite(priceChangeBasePrice) ||
    price <= 0 ||
    priceChangeBasePrice <= 0
  ) {
    return undefined;
  }

  return ((price - priceChangeBasePrice) / priceChangeBasePrice) * 100;
}

export function getMarketTokenNetworkLogoUri({
  tokenNetworkId,
  chainId,
  networkLogoUriMap,
  networkLogoUri,
}: {
  tokenNetworkId?: string;
  chainId: string;
  networkLogoUriMap?: ReadonlyMap<string, string>;
  networkLogoUri: string;
}) {
  if (!tokenNetworkId) {
    return networkLogoUri;
  }

  return (
    networkLogoUriMap?.get(tokenNetworkId) ||
    (tokenNetworkId === chainId
      ? networkLogoUri
      : getNetworkLogoUri(tokenNetworkId))
  );
}

/**
 * Convert raw api item to component token shape
 */
export function transformApiItemToToken(
  item: IMarketTokenListItem & { isNative?: boolean },
  {
    chainId,
    networkLogoUriMap,
    networkLogoUri,
    sortIndex,
    timeRange,
  }: {
    chainId: string;
    networkLogoUriMap?: ReadonlyMap<string, string>;
    networkLogoUri: string;
    sortIndex?: number;
    timeRange?: IMarketTimeRangeValue;
  },
): IMarketToken {
  const tokenNetworkId = item.networkId || chainId;
  const tokenNetworkLogoUri = getMarketTokenNetworkLogoUri({
    tokenNetworkId: item.networkId,
    chainId,
    networkLogoUriMap,
    networkLogoUri,
  });

  const priceChangeValue = item.stock
    ? item.priceChange24hPercent
    : (getMetricValueByTimeRange(item, timeRange, 'priceChange', 'Percent') as
        | string
        | undefined);
  const priceChange = safeNumber(priceChangeValue);
  const transactions = safeNumber(
    getMetricValueByTimeRange(item, timeRange, 'trade', 'Count') as
      | string
      | undefined,
  );
  const uniqueTraders = safeNumber(
    getMetricValueByTimeRange(item, timeRange, 'uniqueWallet', '') as
      | string
      | undefined,
  );
  const turnover = safeNumber(
    getStockVolume24hValue(item) ??
      (getMetricValueByTimeRange(item, timeRange, 'volume', '') as
        | string
        | undefined),
  );
  const buyCount = safeNumber(
    getMetricValueByTimeRange(item, timeRange, 'buy', 'Count') as
      | string
      | undefined,
  );
  const sellCount = safeNumber(
    getMetricValueByTimeRange(item, timeRange, 'sell', 'Count') as
      | string
      | undefined,
  );
  const priceChangeBasePrice = item.stock
    ? safePositiveNumber(item.price24hAgo)
    : getPriceChangeBasePriceByTimeRange({
        item,
        timeRange,
      });

  return {
    id: `${item.address}${item.name}${tokenNetworkLogoUri}${item.symbol}`,
    name: item.name,
    symbol: item.symbol,
    address: item.address,
    price: safeNumber(item.price),
    change24h: priceChange,
    priceChangeRaw: priceChangeValue,
    marketCap: safeNumber(getStockMarketCapValue(item) ?? item.marketCap),
    liquidity: safeNumber(item.liquidity),
    transactions,
    uniqueTraders,
    holders: item.holders || 0,
    turnover,
    tokenImageUri: item.logoUrl || '',
    tokenImageUris: item.logoUrls,
    decimals: item.decimals,
    networkLogoUri: tokenNetworkLogoUri,
    networkId: tokenNetworkId,
    priceChangeBasePrice,
    chainId: tokenNetworkId,
    firstTradeTime: item.firstTradeTime
      ? Number(item.firstTradeTime)
      : undefined,
    sortIndex,
    isNative: item.isNative,
    communityRecognized: item.communityRecognized,
    stock: item.stock,
    stockId: resolveMarketStockId(item),
    walletInfo: {
      buy: buyCount,
      sell: sellCount,
    },
  };
}

export function getTokenAgeInfo(
  firstTradeTime?: number,
): ITokenAgeInfo | undefined {
  if (!firstTradeTime) {
    return undefined;
  }

  const now = Date.now();
  const duration = now - firstTradeTime;

  if (duration <= 0) {
    return undefined;
  }

  if (duration < ONE_DAY) {
    return {
      amount: Math.max(1, Math.round(duration / ONE_HOUR)),
      unit: 'hour',
    };
  }

  if (duration < ONE_MONTH) {
    return {
      amount: Math.max(1, Math.round(duration / ONE_DAY)),
      unit: 'day',
    };
  }

  if (duration < ONE_YEAR) {
    return {
      amount: Math.max(1, Math.round(duration / ONE_MONTH)),
      unit: 'month',
    };
  }

  return {
    amount: Math.max(1, Math.round(duration / ONE_YEAR)),
    unit: 'year',
  };
}
